import{_ as a,o as t,c as s,ah as n}from"./chunks/framework.Cx6lfSeA.js";const m=JSON.parse(`{"title":"Components","description":"Guide to prefab's 115+ declarative UI components — layout, typography, forms, data tables, charts, media, and interactive elements.","frontmatter":{"description":"Guide to prefab's 115+ declarative UI components — layout, typography, forms, data tables, charts, media, and interactive elements.","head":[["link",{"rel":"canonical","href":"https://max-health-inc.github.io/prefab/guide/components"}],["meta",{"property":"og:url","content":"https://max-health-inc.github.io/prefab/guide/components"}],["meta",{"property":"og:description","content":"Guide to prefab's 115+ declarative UI components — layout, typography, forms, data tables, charts, media, and interactive elements."}]]},"headers":[],"relativePath":"guide/components.md","filePath":"guide/components.md","lastUpdated":1785956743000}`),o={name:"guide/components.md"};function i(r,e,l,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /prefab/guide/components.md for this page in Markdown format</div><h1 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h1><p>A prefab UI is just data. You describe what you want as a tree of typed nodes, and the renderer turns that tree into a live interface. There is no JSX, no virtual DOM to reason about, and no framework to learn — only a vocabulary of component functions that you nest inside one another.</p><h2 id="the-mental-model" tabindex="-1">The mental model <a class="header-anchor" href="#the-mental-model" aria-label="Permalink to &quot;The mental model&quot;">​</a></h2><p>Each component is a function that returns a <code>Component</code> instance. Calling it builds one node in the tree; passing other components as its children grows the tree downward. When you are ready to ship, the whole structure serializes to plain <code>$prefab</code> wire JSON, which any prefab-aware client can render.</p><p>Most components share a friendly shape: an optional <strong>props</strong> object first, then an array of <strong>children</strong>.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Column</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  gap: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  children: [</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    H1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Patients&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    Text</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Everyone under your care, at a glance.&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span></code></pre></div><p>Containers like <code>Column</code> and <code>Row</code> hold other nodes; leaf nodes like <code>Text</code> and <code>Badge</code> carry content. Containers take a single props object, with the child nodes under <code>children</code>. Leaf nodes take their content positionally, which is why <code>H1(&#39;Patients&#39;)</code> and <code>Text(&#39;…&#39;)</code> read the way they do.</p><h2 id="how-components-compose" tabindex="-1">How components compose <a class="header-anchor" href="#how-components-compose" aria-label="Permalink to &quot;How components compose&quot;">​</a></h2><p>Composition is the whole game. You build small, meaningful pieces and slot them into larger layouts, the same way you would nest boxes inside boxes. A card lives inside a column, a table lives inside a card, a badge lives inside a table cell. Because every node is data, you can also build trees programmatically — map over rows, conditionally include a section, or factor a repeated fragment into a helper function.</p><p>Props that drive behavior (an <code>onClick</code> action, a reactive <code>cssClass</code>, a <code>from</code> collection) make these static trees come alive without changing the composition model.</p><h2 id="the-categories" tabindex="-1">The categories <a class="header-anchor" href="#the-categories" aria-label="Permalink to &quot;The categories&quot;">​</a></h2><p>prefab groups its 115+ components into a handful of families. Reach for the family that matches your intent:</p><ul><li><strong>Layout</strong> — structural containers that control direction, spacing, and grids (<code>Column</code>, <code>Row</code>, <code>Grid</code>, <code>MasterDetail</code>).</li><li><strong>Typography</strong> — headings, paragraphs, labels, and inline text styles.</li><li><strong>Card &amp; Alert</strong> — grouped content surfaces and status callouts.</li><li><strong>Forms</strong> — inputs, selects, checkboxes, date pickers, and field wrappers.</li><li><strong>Data display</strong> — tables, badges, metrics, and progress indicators.</li><li><strong>Charts</strong> — bar, line, area, pie, radar, scatter, and more, rendered natively as SVG.</li><li><strong>Media</strong> — images, audio, video, embeds, and file drop zones.</li><li><strong>Interactive</strong> — tabs, accordions, dialogs, popovers, and carousels.</li><li><strong>Control flow</strong> — <code>If</code>/<code>Else</code>, <code>ForEach</code>, and reusable <code>Define</code>/<code>Use</code> templates that shape the tree at render time.</li></ul><p>Pick a container, fill it with the leaves and nested containers you need, and let the renderer handle the rest.</p><p>→ See the <a href="/prefab/reference/components">Components reference</a> for the full catalog: every component, its props, and examples.</p>`,16)])])}const g=a(o,[["render",i]]);export{m as __pageData,g as default};
